{
  "company": "CRONUS International Ltd.",
  "messageType": "DataExchange.Definition.Delete",
  "status": "Success",
  "contract": "json",
  "format": "chapters",
  "catalogue": {
    "name": "DataExchange.Definition.Delete",
    "isEnabled": true,
    "filterTableNo": 1222,
    "description": "Deletes a Data Exchange definition that is not referenced.",
    "selectionDescription": "Deletes a definition. Refuses a definition used by a Data Exchange Type or Bank Export/Import Setup.",
    "messageDirection": "Inbound",
    "keywords": [
      "delete data exchange definition"
    ],
    "chargeable": true
  },
  "chapters": {
    "examples": [
      {
        "title": "A successful request",
        "request": {
          "type": "DataExchange.Definition.Delete",
          "data": {
            "code": "INVOICES"
          },
          "lcid": 1033
        },
        "response": {
          "status": "Success",
          "data": {
            "code": "INVOICES"
          }
        }
      },
      {
        "title": "A request refused before any change",
        "request": {
          "type": "DataExchange.Definition.Delete",
          "data": {
            "code": "X160-MISSING"
          },
          "lcid": 1033
        },
        "response": {
          "status": "Error",
          "code": "RecordNotFound",
          "error": "Data Exchange definition X160-MISSING was not found.",
          "parameter": "code",
          "received": "X160-MISSING",
          "expected": "an existing Data Exchange definition",
          "nextStep": "Call DataExchange.Definition.List and use the exact definition code.",
          "hint": "For usage details, call the \"Help.Implementation.Get\" message type with subject \"DataExchange.Definition.Delete\". Always read the help before calling a message type."
        }
      },
      {
        "title": "Refusal: required request data is missing",
        "request": {
          "type": "DataExchange.Definition.Delete",
          "data": {},
          "lcid": 1033
        },
        "response": {
          "status": "Error",
          "code": "MissingParameter",
          "error": "Parameter \"code\" is required.",
          "parameter": "code",
          "received": "not supplied",
          "expected": "a JSON string of at most 20 characters",
          "nextStep": "Send \"code\" as a JSON string of at most 20 characters and retry.",
          "hint": "For usage details, call the \"Help.Implementation.Get\" message type with subject \"DataExchange.Definition.Delete\". Always read the help before calling a message type."
        }
      }
    ],
    "overview": "Deletes one Data Exchange definition after checking references."
  }
}

