          "lcid": 1033
        },
        "response": {
          "status": "Success",
          "data": {
            "code": "INVOICES",
            "name": "Invoice import",
            "type": "Generic Import"
          }
        }
      },
      {
        "title": "A request refused before any change",
        "request": {
          "type": "DataExchange.Definition.Export",
          "data": {
            "code": "X160-MISSING",
            "inline": true
          },
          "lcid": 1033
        },
        "response": {
          "status": "Error",
          "code": "RecordNotFound",
          "error": "No Data Exch. Def exists for code 'X160-MISSING'.",
          "parameter": "code",
          "received": "X160-MISSING",
          "expected": "Use a code returned by DataExchange.Definition.List.",
          "nextStep": "Use a code returned by DataExchange.Definition.List.",
          "hint": "For usage details, call the \"Help.Implementation.Get\" message type with subject \"DataExchange.Definition.Export\". Always read the help before calling a message type."
        }
      },
      {
        "title": "Refusal: required request data is missing",
        "request": {
          "type": "DataExchange.Definition.Export",
          "data": {},
          "lcid": 1033
        },
        "response": {
          "status": "Error",
          "code": "MissingParameter",
          "error": "Missing required 'code' in the request.",
          "parameter": "code",
          "received": "(missing)",
          "expected": "a JSON string",
          "nextStep": "Provide \"code\" and send the request again.",
          "hint": "For usage details, call the \"Help.Implementation.Get\" message type with subject \"DataExchange.Definition.Export\". Always read the help before calling a message type."
        }
      }
    ],
    "overview": "Returns the definition header (code, name and type) by default. With inline true, also returns the definition XML as contentBase64. With storageCode and path, writes the XML to storage; both XML destinations may be requested."
