{
  "company": "CRONUS International Ltd.",
  "messageType": "DataExchange.Definition.Import",
  "status": "Success",
  "contract": "json",
  "format": "chapters",
  "catalogue": {
    "name": "DataExchange.Definition.Import",
    "isEnabled": true,
    "filterTableNo": 1222,
    "description": "Installs Data Exchange definitions with their lines, columns and mappings from the standard definition XML.",
    "selectionDescription": "Creates or replaces Data Exchange definitions from an XML file, the same file the Export Data Exchange Definition action writes and DataExchange.Definition.Export returns.",
    "messageDirection": "Inbound",
    "keywords": [
      "install data exchange definition",
      "import definition xml",
      "load file format",
      "copy data exchange definition",
      "add import format"
    ],
    "chargeable": true
  },
  "chapters": {
    "examples": [
      {
        "title": "A successful request",
        "request": {
          "type": "DataExchange.Definition.Import",
          "data": {
            "storageCode": "ARCHIVE",
            "path": "definitions/invoices.xml"
          },
          "lcid": 1033
        },
        "response": {
          "status": "Success",
          "data": {
            "codes": [
              "INVOICES"
            ],
            "lineDefs": 1,
            "mappings": 1,
            "overwritten": []
          }
        }
      },
      {
        "title": "A request refused before any change",
        "request": {
          "type": "DataExchange.Definition.Import",
          "data": {
            "contentBase64": "not-base64!"
          },
          "lcid": 1033
        },
        "response": {
          "status": "Error",
          "code": "InvalidParameterFormat",
          "error": "Parameter \"contentBase64\" is not valid base64 content.",
          "parameter": "contentBase64",
          "expected": "base64 content",
          "nextStep": "Encode the file bytes as standard base64 and send them again.",
          "hint": "For usage details, call the \"Help.Implementation.Get\" message type with subject \"DataExchange.Definition.Import\". Always read the help before calling a message type."
        }
      },
      {
        "title": "Refusal: required request data is missing",
        "request": {
          "type": "DataExchange.Definition.Import",
          "data": {},
          "lcid": 1033
        },
        "response": {
          "status": "Error",
          "code": "MultipleErrors",
          "error": "2 problems in the request. Nothing was changed.",
          "errors": [
            {
              "code": "MissingParameter",
              "error": "Parameter \"storageCode\" is required.",
              "parameter": "storageCode",
              "received": "not supplied",
              "expected": "a JSON string of at most 20 characters",
              "nextStep": "Send \"storageCode\" as a JSON string of at most 20 characters and retry."
            },
            {
              "code": "MissingParameter",
              "error": "Parameter \"path\" is required.",
              "parameter": "path",
              "received": "not supplied",
              "expected": "a JSON string of at most 2048 characters",
              "nextStep": "Send \"path\" as a JSON string of at most 2048 characters and retry."
            }
          ],
          "hint": "For usage details, call the \"Help.Implementation.Get\" message type with subject \"DataExchange.Definition.Import\". Always read the help before calling a message type."
        }
      }
    ],
    "overview": "Reads the XML from storageCode and path, from contentBase64 (at most 1 MB) or from a complete chunked upload (uploadId, which is consumed), and installs it with the base XMLport Imp / Exp Data Exch Def & Map. newCode installs a single definition under another code."
  }
}

